window.MGProseData("0844ee63b0353674256d56a21a43cd6582c42b91a6ef8e67456baa7ef83b3c44",{"html":"\u003cp>\u003cstrong>S1．结论成立。\u003c/strong>\u003c/p>\n\u003cp>取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>a\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo>∈\u003c/mo>\u003cmi>A\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">a_0\\in A\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，以及收缩\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>h\u003c/mi>\u003cmo>:\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo>×\u003c/mo>\u003cmi>I\u003c/mi>\u003cmo>⟶\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>h\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmi>h\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>a\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nh:A\\times I\\longrightarrow A,\\qquad h(a,0)=a,\\quad h(a,1)=a_0.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n子复形包含 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>A\u003c/mi>\u003cmo>↪\u003c/mo>\u003cmi>Y\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A\\hookrightarrow Y\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是上纤维化，因而具有同伦延拓性质。将 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>h\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">h\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 与 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">id\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi>Y\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\operatorname{id}_Y\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 延拓为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>H\u003c/mi>\u003cmo>:\u003c/mo>\u003cmi>Y\u003c/mi>\u003cmo>×\u003c/mo>\u003cmi>I\u003c/mi>\u003cmo>⟶\u003c/mo>\u003cmi>Y\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>H\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">id\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi>Y\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmi>H\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmrow>\u003cmi>A\u003c/mi>\u003cmo>×\u003c/mo>\u003cmi>I\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi>h\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nH:Y\\times I\\longrightarrow Y,\\qquad H_0=\\operatorname{id}_Y,\\quad H|_{A\\times I}=h.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n由于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>H\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">H_1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>A\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 上恒等于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>a\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">a_0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，它经商映射 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>q\u003c/mi>\u003cmo>:\u003c/mo>\u003cmi>Y\u003c/mi>\u003cmo>→\u003c/mo>\u003cmi>Y\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>A\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q:Y\\to Y/A\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 分解为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>H\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi>g\u003c/mi>\u003cmi>q\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>g\u003c/mi>\u003cmo>:\u003c/mo>\u003cmi>Y\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>A\u003c/mi>\u003cmo>⟶\u003c/mo>\u003cmi>Y\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nH_1=gq,\\qquad g:Y/A\\longrightarrow Y.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n所以 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>g\u003c/mi>\u003cmi>q\u003c/mi>\u003cmo>≃\u003c/mo>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">id\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi>Y\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">gq\\simeq\\operatorname{id}_Y\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>还需验证另一侧，并解释同伦为何下降。对每个 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>t\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">t\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，有\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>H\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>⊆\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nH(A,t)\\subseteq A,\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n因此 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>q\u003c/mi>\u003cmi>H\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmo>−\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">qH(-,t)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>A\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 上取同一个值。故公式\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>H\u003c/mi>\u003cmo stretchy=\"true\">‾\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">]\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmi>q\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>H\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\overline H([y],t)=q(H(y,t))\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n良定义。其连续性来自 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>q\u003c/mi>\u003cmo>×\u003c/mo>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">id\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi>I\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q\\times\\operatorname{id}_I\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是商映射：有限 CW 复形 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>Y\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">Y\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 紧致，闭子复形 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>A\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的商 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>Y\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>A\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">Y/A\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为 Hausdorff 空间，所以这是从紧空间到 Hausdorff 空间的连续满射。于是\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>H\u003c/mi>\u003cmo stretchy=\"true\">‾\u003c/mo>\u003c/mover>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">id\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmi>Y\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>A\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>H\u003c/mi>\u003cmo stretchy=\"true\">‾\u003c/mo>\u003c/mover>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi>q\u003c/mi>\u003cmi>g\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\overline H_0=\\operatorname{id}_{Y/A},\\qquad \\overline H_1=qg.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n因此 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>q\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 与 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>g\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">g\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 互为同伦逆。\u003c/p>\n\u003cp>注意，下降的是 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>q\u003c/mi>\u003cmi>H\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">qH\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>；关键条件是整个同伦始终将 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>A\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 映入 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>A\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003chr>\n\u003cp>\u003cstrong>S2．结论成立，楔点可取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>D\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">D\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的任一选定 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>-胞腔与悬挂的一个悬挂点。\u003c/strong>\u003c/p>\n\u003cp>先说明所用的映射锥事实。记\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>f\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi>D\u003c/mi>\u003cmsub>\u003cmo>∪\u003c/mo>\u003cmi>f\u003c/mi>\u003c/msub>\u003cmi>C\u003c/mi>\u003cmi>L\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nC_f=D\\cup_f CL.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>g\u003c/mi>\u003cmo>:\u003c/mo>\u003cmi>L\u003c/mi>\u003cmo>→\u003c/mo>\u003cmi>D\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f,g:L\\to D\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 经 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo>:\u003c/mo>\u003cmi>L\u003c/mi>\u003cmo>×\u003c/mo>\u003cmi>I\u003c/mi>\u003cmo>→\u003c/mo>\u003cmi>D\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F:L\\times I\\to D\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 同伦，则 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>f\u003c/mi>\u003c/msub>\u003cmo>≃\u003c/mo>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>g\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">C_f\\simeq C_g\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。具体地，令锥坐标 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>t\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">t=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为底面、\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>t\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">t=1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为锥顶，定义一个在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>D\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">D\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 上为恒等的映射\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"normal\">Φ\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo>:\u003c/mo>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>f\u003c/mi>\u003c/msub>\u003cmo>⟶\u003c/mo>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>g\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">]\u003c/mo>\u003cmo>⟼\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">{\u003c/mo>\u003cmtable rowspacing=\"0.36em\" columnalign=\"left left\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>≤\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003c/mstyle>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>t\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">]\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003c/mstyle>\u003cmo>≤\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmn>1.\u003c/mn>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mrow>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\Phi_F:C_f\\longrightarrow C_g,\\qquad\n[x,t]\\longmapsto\n\\begin{cases}\nF(x,2t),\u0026amp;0\\le t\\le \\tfrac12,\\\\\n[x,2t-1],\u0026amp;\\tfrac12\\le t\\le1.\n\\end{cases}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n两段在接合处相容，也与底面的粘合相容。\u003c/p>\n\u003cp>反向同伦给出反向映射。两个复合在每条锥线上都先沿同伦路径往返，再沿原锥线前进。将往返路径的行进长度连续缩至零，再重参数化锥线，便得到到恒等映射的同伦；这些同伦在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>D\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">D\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 上固定。因此上述映射确为同伦等价。\u003c/p>\n\u003cp>现在选定 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>D\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">D\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的一个 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>-胞腔 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">d_0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。包含 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>i\u003c/mi>\u003cmo>:\u003c/mo>\u003cmi>L\u003c/mi>\u003cmo>↪\u003c/mo>\u003cmi>D\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">i:L\\hookrightarrow D\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 零伦；由于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>D\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">D\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 路径连通，可在原零伦后接一条路径，使终点为常值映射 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>c\u003c/mi>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">c_{d_0}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。于是\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>Y\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>≃\u003c/mo>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmsub>\u003cmi>c\u003c/mi>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003c/msub>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi>D\u003c/mi>\u003cmsub>\u003cmo>∨\u003c/mo>\u003cmrow>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>s\u003c/mi>\u003cmo>−\u003c/mo>\u003c/msub>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>C\u003c/mi>\u003cmi>L\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>L\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmi>D\u003c/mi>\u003cmo>∨\u003c/mo>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi>L\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nY=C_i\\simeq C_{c_{d_0}}\n=D\\vee_{d_0=s_-}(CL/L)\n=D\\vee\\Sigma L.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n这里 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>s\u003c/mi>\u003cmo>−\u003c/mo>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">s_-\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是把锥底 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>L\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">L\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 压成的悬挂点，另一个悬挂点来自锥顶。因此使用的是\u003cstrong>非约化悬挂\u003c/strong>，不需要为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>L\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">L\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 选择基点。\u003c/p>\n\u003cp>更换 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>D\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">D\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 中所选的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>-胞腔时，两常值映射由路径给出同伦，上述映射锥论证仍适用。两个悬挂点则可由悬挂坐标反向的同胚交换。\u003c/p>\n\u003chr>\n\u003cp>\u003cstrong>S3．取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmrow>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003cmi mathvariant=\"double-struck\">P\u003c/mi>\u003c/mrow>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathbb{RP}^2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的双锥，即可得到所需实例。\u003c/strong>\u003c/p>\n\u003cp>先记录供 S3–S5 使用的删点事实。对有限单纯复形 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>K\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">K\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的顶点 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，定义删点子复形\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>D\u003c/mi>\u003cmi>v\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>σ\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmi>K\u003c/mi>\u003cmo>:\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo mathvariant=\"normal\">∉\u003c/mo>\u003cmi>σ\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nD_v=\\{\\sigma\\in K:v\\notin\\sigma\\}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n则\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>K\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>∖\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmo>↘\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>D\u003c/mi>\u003cmi>v\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n|K|\\setminus\\{v\\}\\ \\searrow\\ |D_v|.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n事实上，若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>x\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmi>v\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">x\\ne v\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的重心坐标为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>λ\u003c/mi>\u003cmi>w\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(\\lambda_w)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>λ\u003c/mi>\u003cmi>v\u003c/mi>\u003c/msub>\u003cmo>\u0026lt;\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\lambda_v\u0026lt;1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，可以定义\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>r\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmsub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi>v\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>r\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmsub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi>w\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmsub>\u003cmi>λ\u003c/mi>\u003cmi>w\u003c/mi>\u003c/msub>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>λ\u003c/mi>\u003cmi>v\u003c/mi>\u003c/msub>\u003c/mrow>\u003c/mfrac>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>w\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nr(x)_v=0,\\qquad\nr(x)_w=\\frac{\\lambda_w}{1-\\lambda_v}\\quad(w\\ne v).\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n线性同伦 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>−\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>t\u003c/mi>\u003cmi>r\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(1-t)x+tr(x)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 始终位于包含 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>x\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">x\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的原单形内，不经过 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，并固定 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>D\u003c/mi>\u003cmi>v\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|D_v|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，故是强形变收缩。\u003c/p>\n\u003cp>现在取题给的三角剖分 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>L\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">L\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，添加两个新顶点 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>v\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">a,v\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，令\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>K\u003c/mi>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo>∗\u003c/mo>\u003cmi>L\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsub>\u003cmo>∪\u003c/mo>\u003cmi>L\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo>∗\u003c/mo>\u003cmi>L\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nK=(a*L)\\cup_L(v*L).\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n于是\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>K\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≅\u003c/mo>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>L\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≅\u003c/mo>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmsup>\u003cmrow>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003cmi mathvariant=\"double-struck\">P\u003c/mi>\u003c/mrow>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n|K|\\cong\\Sigma|L|\\cong\\Sigma\\mathbb{RP}^2.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n任取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>L\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">L\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的顶点 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>w\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">w\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，令 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>B\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">B\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为边 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>w\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\{v,w\\}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 及其全部面组成的子复形。\u003c/p>\n\u003cp>逐项验证：\u003c/p>\n\u003cul>\n\u003cli>\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>D\u003c/mi>\u003cmi>v\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo>∗\u003c/mo>\u003cmi>L\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">D_v=a*L\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，其实现是非空可缩的锥。因此 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>K\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>∖\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|K|\\setminus\\{v\\}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 非空可缩。\u003c/li>\n\u003cli>\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>B\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|B|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是闭区间，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>B\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>∖\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|B|\\setminus\\{v\\}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是含端点 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>w\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">w\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的半开区间。两者均可沿区间收缩到 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>w\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">w\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，故包含映射是同伦等价。\u003c/li>\n\u003cli>对非空空间 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>Z\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">Z\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，悬挂的两个加厚锥给出的约化 Mayer–Vietoris 序列给出\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>H\u003c/mi>\u003cmo stretchy=\"true\">~\u003c/mo>\u003c/mover>\u003cmrow>\u003cmi>q\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi>Z\u003c/mi>\u003cmo separator=\"true\">;\u003c/mo>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≅\u003c/mo>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>H\u003c/mi>\u003cmo stretchy=\"true\">~\u003c/mo>\u003c/mover>\u003cmi>q\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>Z\u003c/mi>\u003cmo separator=\"true\">;\u003c/mo>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>q\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>0.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\widetilde H_{q+1}(\\Sigma Z;\\mathbb Z)\n\\cong \\widetilde H_q(Z;\\mathbb Z),\\qquad q\\ge0.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n而 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmrow>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003cmi mathvariant=\"double-struck\">P\u003c/mi>\u003c/mrow>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathbb{RP}^2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的胞腔链复形中，二维边界为乘以 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，一维边界为零。因此\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>H\u003c/mi>\u003cmo stretchy=\"true\">~\u003c/mo>\u003c/mover>\u003cmi>q\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>K\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo separator=\"true\">;\u003c/mo>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">{\u003c/mo>\u003cmtable rowspacing=\"0.36em\" columnalign=\"left left\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>2\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>q\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>q\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmn>2.\u003c/mn>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mrow>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\widetilde H_q(|K|;\\mathbb Z)=\n\\begin{cases}\n\\mathbb Z/2,\u0026amp;q=2,\\\\\n0,\u0026amp;q\\ne2.\n\\end{cases}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/li>\n\u003c/ul>\n\u003cp>所以 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>K\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|K|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的约化有理同调全零，但其二阶整数同调非零，故不可缩。\u003c/p>\n\u003chr>\n\u003cp>\u003cstrong>S4．全部目标成立。可能的同伦类型恰为非空有限单纯复形的非约化悬挂；可缩的充要条件是顶点 link 的约化整数同调全零。\u003c/strong>\u003c/p>\n\u003cp>令\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>D\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>D\u003c/mi>\u003cmi>v\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi mathvariant=\"normal\">Λ\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">lk\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi>K\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>τ\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmi>D\u003c/mi>\u003cmo>:\u003c/mo>\u003cmi>τ\u003c/mi>\u003cmo>∪\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmo>∈\u003c/mo>\u003cmi>K\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nD=D_v,\\qquad\n\\Lambda=\\operatorname{lk}_K(v)\n=\\{\\tau\\in D:\\tau\\cup\\{v\\}\\in K\\}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>\u003cstrong>先证明分类。\u003c/strong> 由 S3 的形变收缩，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>D\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≃\u003c/mo>\u003cmi>O\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|D|\\simeq O\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，所以 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>D\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|D|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 非空可缩。\u003c/p>\n\u003cp>此外，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">Λ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmi mathvariant=\"normal\">∅\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|\\Lambda|\\ne\\varnothing\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。否则没有边连接 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 与其他顶点，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 就是 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>X\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">X\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的孤立点，也是 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>C\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">C\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的独立路径分支。但\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>O\u003c/mi>\u003cmo>∩\u003c/mo>\u003cmi>C\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>C\u003c/mi>\u003cmo>∖\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmo>⟶\u003c/mo>\u003cmi>C\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nO\\cap C=C\\setminus\\{v\\}\\longrightarrow C\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n遗漏这个路径分支，不可能在路径分支集合上诱导双射，因而不可能是同伦等价。\u003c/p>\n\u003cp>现在有单纯复形分解\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>K\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>D\u003c/mi>\u003cmsub>\u003cmo>∪\u003c/mo>\u003cmi mathvariant=\"normal\">Λ\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo>∗\u003c/mo>\u003cmi mathvariant=\"normal\">Λ\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nK=D\\cup_\\Lambda(v*\\Lambda).\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n应用 S1：\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>D\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|D|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是有限 CW 复形 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>X\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">X\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的非空可缩子复形，故\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>X\u003c/mi>\u003cmo>≃\u003c/mo>\u003cmi>X\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>D\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≅\u003c/mo>\u003cmi>C\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">Λ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">Λ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≅\u003c/mo>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">Λ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nX\\simeq X/|D|\n\\cong C|\\Lambda|/|\\Lambda|\n\\cong\\Sigma|\\Lambda|.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n这证明了必要方向。\u003c/p>\n\u003cp>\u003cstrong>实现全部类型。\u003c/strong> 对任意非空有限单纯复形 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>L\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">L\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，取\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>K\u003c/mi>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo>∗\u003c/mo>\u003cmi>L\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsub>\u003cmo>∪\u003c/mo>\u003cmi>L\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo>∗\u003c/mo>\u003cmi>L\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>B\u003c/mi>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>w\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmtext> 及其全部面\u003c/mtext>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nK=(a*L)\\cup_L(v*L),\\qquad B=\\{v,w\\}\\text{ 及其全部面},\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n其中 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>v\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">a,v\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是新顶点，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>w\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">w\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>L\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">L\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的任一顶点。S3 对删点空间及 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>B\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">B\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的验证完全不依赖于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsup>\u003cmrow>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003cmi mathvariant=\"double-struck\">P\u003c/mi>\u003c/mrow>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">L=\\mathbb{RP}^2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，所以这个构造满足全部原条件，并且\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>K\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≅\u003c/mo>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>L\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n|K|\\cong\\Sigma|L|.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n因此可能同伦类型的集合准确地是\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>L\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo stretchy=\"false\">]\u003c/mo>\u003cmo>:\u003c/mo>\u003cmi>L\u003c/mi>\u003cmtext> 为非空有限单纯复形\u003c/mtext>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\\{[\\Sigma|L|]:L\\text{ 为非空有限单纯复形}\\}.}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n这里并不声称不同 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>L\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">L\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 一定给出不同同伦类型；S6 将说明这种唯一性不成立。\u003c/p>\n\u003cp>\u003cstrong>给出仅依赖局部关联数据的判据。\u003c/strong> 任意排列 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 以外的顶点。对 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>q\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q\\ge0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，令\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmi>q\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmunder>\u003cmo>⨁\u003c/mo>\u003cmrow>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>w\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo>…\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>w\u003c/mi>\u003cmi>q\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmo>∈\u003c/mo>\u003cmi>K\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmsub>\u003cmi>w\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo>…\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>w\u003c/mi>\u003cmi>q\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">]\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>w\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo>\u0026lt;\u003c/mo>\u003cmo>⋯\u003c/mo>\u003cmo>\u0026lt;\u003c/mo>\u003cmsub>\u003cmi>w\u003c/mi>\u003cmi>q\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\mathcal C_q=\n\\bigoplus_{\\{v,w_0,\\ldots,w_q\\}\\in K}\n\\mathbb Z[w_0,\\ldots,w_q],\n\\qquad w_0\u0026lt;\\cdots\u0026lt;w_q.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n定义\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"normal\">∂\u003c/mi>\u003cmi>q\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmsub>\u003cmi>w\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo>…\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>w\u003c/mi>\u003cmi>q\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">]\u003c/mo>\u003cmo>=\u003c/mo>\u003cmunderover>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>i\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cmi>q\u003c/mi>\u003c/munderover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi>i\u003c/mi>\u003c/msup>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmsub>\u003cmi>w\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo>…\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>w\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo>…\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>w\u003c/mi>\u003cmi>q\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">]\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>q\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\partial_q[w_0,\\ldots,w_q]\n=\\sum_{i=0}^q(-1)^i[w_0,\\ldots,\\widehat w_i,\\ldots,w_q]\n\\quad(q\\ge1),\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n并定义增广\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>ε\u003c/mi>\u003cmo>:\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo>→\u003c/mo>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmi>w\u003c/mi>\u003cmo stretchy=\"false\">]\u003c/mo>\u003cmo>↦\u003c/mo>\u003cmn>1.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\varepsilon:\\mathcal C_0\\to\\mathbb Z,\\qquad [w]\\mapsto1.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n这是 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">Λ\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\Lambda\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的增广单纯链复形。每个生成元及其边界关联，都由包含 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的单形之间的面关系确定。\u003c/p>\n\u003cp>所求判据为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmi>X\u003c/mi>\u003cmtext> 可缩\u003c/mtext>\u003cmtext>  \u003c/mtext>\u003cmo>⟺\u003c/mo>\u003cmtext>  \u003c/mtext>\u003cmn>0\u003c/mn>\u003cmo>⟶\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmi>d\u003c/mi>\u003c/msub>\u003cmo>⟶\u003c/mo>\u003cmo>⋯\u003c/mo>\u003cmo>⟶\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmover>\u003cmo stretchy=\"true\" minsize=\"3.0em\">→\u003c/mo>\u003cmpadded width=\"+0.6em\" lspace=\"0.3em\">\u003cmi>ε\u003c/mi>\u003c/mpadded>\u003c/mover>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmo>⟶\u003c/mo>\u003cmn>0\u003c/mn>\u003cmtext> 正合\u003c/mtext>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\nX\\text{ 可缩}\n\\iff\n0\\longrightarrow\\mathcal C_d\\longrightarrow\\cdots\n\\longrightarrow\\mathcal C_0\n\\xrightarrow{\\varepsilon}\\mathbb Z\\longrightarrow0\n\\text{ 正合}.\n}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n这里 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>d\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>dim\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmi mathvariant=\"normal\">Λ\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">d=\\dim\\Lambda\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。这是有限整数矩阵的正合性问题，可以通过整数线性代数及 Smith 标准形检验。\u003c/p>\n\u003cp>证明如下：\u003c/p>\n\u003cul>\n\u003cli>若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>X\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">X\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 可缩，则 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>X\u003c/mi>\u003cmo>≃\u003c/mo>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">Λ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">X\\simeq\\Sigma|\\Lambda|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 以及悬挂同调同构给出\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>H\u003c/mi>\u003cmo stretchy=\"true\">~\u003c/mo>\u003c/mover>\u003cmi>q\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">Λ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo separator=\"true\">;\u003c/mo>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003cmspace width=\"2em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>q\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\widetilde H_q(|\\Lambda|;\\mathbb Z)=0\\qquad(q\\ge0),\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n所以上述增广链复形正合。\u003c/li>\n\u003cli>反之，正合性说明 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">Λ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|\\Lambda|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 非空、连通且约化整数同调全零。有限单纯复形的连通性蕴含路径连通性。悬挂的两个加厚锥均可缩，交集同伦等价于路径连通的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">Λ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|\\Lambda|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，故 van Kampen 定理给出\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>π\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">Λ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\pi_1(\\Sigma|\\Lambda|)=0.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n悬挂同调同构又说明其约化整数同调全零。\u003c/li>\n\u003c/ul>\n\u003cp>最后，单连通且整数同调平凡的 CW 复形可缩：若存在非零高阶同伦群，取最小的这样的次数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>n\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，Hurewicz 定理将给出非零 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>H\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">H_n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，矛盾。因此所有同伦群均为零，再由 CW 复形的 Whitehead 定理得到它与一点同伦等价。应用于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">Λ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\Sigma|\\Lambda|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，即可得 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>X\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">X\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 可缩。\u003c/p>\n\u003chr>\n\u003cp>\u003cstrong>S5．不一定。去掉 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>B\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">B\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 后，只新增 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">S^0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 这一种同伦类型。\u003c/strong>\u003c/p>\n\u003cp>仍令 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>D\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>D\u003c/mi>\u003cmi>v\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">D=D_v\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>、\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">Λ\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">lk\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi>K\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\Lambda=\\operatorname{lk}_K(v)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。删点形变收缩说明 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>D\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|D|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 非空可缩。\u003c/p>\n\u003cp>若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">Λ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmi mathvariant=\"normal\">∅\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|\\Lambda|\\ne\\varnothing\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，S4 的商空间论证仍然适用，得到\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>K\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≃\u003c/mo>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">Λ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n|K|\\simeq\\Sigma|\\Lambda|.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n这部分不需要 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>B\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">B\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">Λ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">∅\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|\\Lambda|=\\varnothing\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 孤立，因而\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>K\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>D\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>⨿\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmo>≃\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmo>∗\u003c/mo>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmo>⨿\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n|K|=|D|\\amalg\\{v\\}\\simeq\\{\\ast\\}\\amalg\\{v\\}=S^0.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n这个类型确实可以实现：取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>K\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">K\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 仅由两个孤立顶点 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>w\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v,w\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 组成。删去 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 后只剩一点，满足题设。\u003c/p>\n\u003cp>非空空间的非约化悬挂总是路径连通，而 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">S^0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 有两个路径分支。因此它不可能同伦等价于任何非空有限复形的悬挂。\u003c/p>\n\u003chr>\n\u003cp>\u003cstrong>S6．不成立。环面与 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msup>\u003cmo>∨\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msup>\u003cmo>∨\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">S^1\\vee S^1\\vee S^2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 给出反例。\u003c/strong>\u003c/p>\n\u003cp>取有限三角剖分使\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>L\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≅\u003c/mo>\u003cmsup>\u003cmi>T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msup>\u003cmo>×\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msup>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>L\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≅\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msup>\u003cmo>∨\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msup>\u003cmo>∨\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n|L_1|\\cong T^2=S^1\\times S^1,\\qquad\n|L_2|\\cong S^1\\vee S^1\\vee S^2.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n第二个有限单纯复形可具体构造为：取两个三角形的边界和一个四面体的边界，将它们各自的一个顶点识别，其他顶点保持不同。\u003c/p>\n\u003cp>二者不同伦等价，因为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>π\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>L\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≅\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>π\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>L\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≅\u003c/mo>\u003cmsub>\u003cmi>F\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">;\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\pi_1(|L_1|)\\cong\\mathbb Z^2,\\qquad\n\\pi_1(|L_2|)\\cong F_2;\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n前者交换，后者不交换。\u003c/p>\n\u003cp>下面验证它们的悬挂同伦等价。记约化悬挂为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\Sigma_r\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。对以顶点为基点的非空有限复形 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>Z\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">Z\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，非约化悬挂中经过该基点、连接两个悬挂点的弧是可缩子复形。将它压成一点得到 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msub>\u003cmi>Z\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\Sigma_r Z\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，所以由 S1，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi>Z\u003c/mi>\u003cmo>≃\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msub>\u003cmi>Z\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\Sigma Z\\simeq\\Sigma_r Z.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n又因约化悬挂保持有限楔和，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msup>\u003cmo>∨\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msup>\u003cmo>∨\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≅\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>∨\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>∨\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\Sigma_r(S^1\\vee S^1\\vee S^2)\n\\cong S^2\\vee S^2\\vee S^3.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>为验证环面的分裂，令\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>:\u003c/mo>\u003cmsup>\u003cmi>T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>→\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\np_1,p_2:T^2\\to S^1\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n为两个投影，令\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>q\u003c/mi>\u003cmo>:\u003c/mo>\u003cmsup>\u003cmi>T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>⟶\u003c/mo>\u003cmsup>\u003cmi>T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msup>\u003cmo>∨\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≅\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nq:T^2\\longrightarrow T^2/(S^1\\vee S^1)\\cong S^2\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n压缩标准 CW 结构的一维骨架。把悬挂坐标分成三段并压缩分界面，得到悬挂的标准挤压映射\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">Δ\u003c/mi>\u003cmo>:\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msub>\u003cmsup>\u003cmi>T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>⟶\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msub>\u003cmsup>\u003cmi>T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>∨\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msub>\u003cmsup>\u003cmi>T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>∨\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msub>\u003cmsup>\u003cmi>T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\Delta:\\Sigma_rT^2\\longrightarrow\n\\Sigma_rT^2\\vee\\Sigma_rT^2\\vee\\Sigma_rT^2.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n定义\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>∨\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>∨\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msub>\u003cmi>q\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>∘\u003c/mo>\u003cmi mathvariant=\"normal\">Δ\u003c/mi>\u003cmo>:\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msub>\u003cmsup>\u003cmi>T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>⟶\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>∨\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>∨\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nF=(\\Sigma_rp_1\\vee\\Sigma_rp_2\\vee\\Sigma_rq)\\circ\\Delta:\n\\Sigma_rT^2\\longrightarrow S^2\\vee S^2\\vee S^3.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n由悬挂同调同构：\u003c/p>\n\u003cul>\n\u003cli>在二阶同调上，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>F\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F_*\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 对应\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo>∗\u003c/mo>\u003c/mrow>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmo>∗\u003c/mo>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>:\u003c/mo>\u003cmsub>\u003cmi>H\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi>T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo separator=\"true\">;\u003c/mo>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmover>\u003cmo stretchy=\"true\" minsize=\"3.0em\">→\u003c/mo>\u003cmpadded width=\"+0.6em\" lspace=\"0.3em\">\u003cmo lspace=\"0em\" rspace=\"0em\">≅\u003c/mo>\u003c/mpadded>\u003c/mover>\u003cmsup>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n(p_{1*},p_{2*}):H_1(T^2;\\mathbb Z)\\xrightarrow{\\cong}\\mathbb Z^2.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/li>\n\u003cli>在三阶同调上，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>F\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F_*\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 对应\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msub>\u003cmo>:\u003c/mo>\u003cmsub>\u003cmi>H\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi>T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo separator=\"true\">;\u003c/mo>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmover>\u003cmo stretchy=\"true\" minsize=\"3.0em\">→\u003c/mo>\u003cmpadded width=\"+0.6em\" lspace=\"0.3em\">\u003cmo lspace=\"0em\" rspace=\"0em\">≅\u003c/mo>\u003c/mpadded>\u003c/mover>\u003cmsub>\u003cmi>H\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo separator=\"true\">;\u003c/mo>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nq_*:H_2(T^2;\\mathbb Z)\\xrightarrow{\\cong}H_2(S^2;\\mathbb Z).\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n这个同构也可直接由胞腔链复形看出：商映射保留唯一的二维胞腔。\u003c/li>\n\u003cli>其余约化同调群均为零。\u003c/li>\n\u003c/ul>\n\u003cp>因此 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是整数同调等价。源与靶都是单连通 CW 复形，满足同调版 Whitehead 定理的适用条件，故 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是同伦等价。于是\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>L\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≃\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>∨\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>∨\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msup>\u003cmo>≃\u003c/mo>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>L\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>L\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≄\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>L\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\n\\Sigma|L_1|\n\\simeq S^2\\vee S^2\\vee S^3\n\\simeq\\Sigma|L_2|,\n\\qquad |L_1|\\not\\simeq|L_2|.\n}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n","source":"assets/content/0844ee63b0353674256d56a21a43cd6582c42b91a6ef8e67456baa7ef83b3c44.html"});
